GRAMMAR_TOPICS=[_g(*x) for x in [["pronouns","Personal pronouns","Use من, تو, او, ما, شما and آنها.",["من دانشجو هستم.","او معلم است."]],["ezafe","Ezafe","Link nouns to modifiers and possessors.",["کتابِ خوب","دوستِ علی"]],["present-copula","Present copula","Form basic identity statements.",["من ایرانی هستم.","این خانه است."]],["negation","Negation","Make simple negative statements.",["این کتاب نیست.","من خسته نیستم."]],["questions","Questions","Ask basic everyday questions.",["این چیست؟","کجا هستی؟"]],["present-progressive","Present forms","Talk about current and habitual actions.",["من فارسی می‌خوانم.","او کار می‌کند."]],["plural","Plural nouns","Refer to more than one thing.",["کتاب‌ها روی میز هستند.","دوست‌ها آمدند."]],["prepositions","Prepositions","Express location and relationships.",["در خانه هستم.","با دوستم می‌روم."]]]]
