VOCABULARY_SETS=[_v(*x) for x in [["greetings_a1","Greetings",[["سلام","phrase","hello","سلام!"],["خداحافظ","phrase","goodbye","خداحافظ!"],["ممنون","phrase","thanks","ممنون."],["نام","noun","name","نام من علی است."]]],["family_a1","Family",[["مادر","noun","mother","مادرم در خانه است."],["پدر","noun","father","پدرم کار می‌کند."],["خواهر","noun","sister","خواهر من دانشجو است."],["برادر","noun","brother","برادرم اینجاست."]]],["home_a1","Home",[["خانه","noun","home","خانه من کوچک است."],["اتاق","noun","room","اتاق من روشن است."],["میز","noun","table","کتاب روی میز است."],["در","noun","door","در باز است."]]],["daily_a1","Daily life",[["صبح","noun","morning","صبح کار می‌کنم."],["کار","noun","work","کار دارم."],["خواندن","verb","read","کتاب می‌خوانم."],["خوابیدن","verb","sleep","شب می‌خوابم."]]],["food_a1","Food and shopping",[["آب","noun","water","آب می‌خواهم."],["نان","noun","bread","نان تازه است."],["چای","noun","tea","چای می‌نوشم."],["قیمت","noun","price","قیمت این چقدر است؟"]]],["places_a1","Places and directions",[["خیابان","noun","street","این خیابان کجاست؟"],["ایستگاه","noun","station","ایستگاه نزدیک است."],["راست","noun","right","به راست برو."],["چپ","noun","left","به چپ برو."]]],["communication_a1","Communication",[["کمک","noun","help","کمک می‌خواهم."],["لطفاً","adverb","please","لطفاً تکرار کنید."],["فهمیدن","verb","understand","نمی‌فهمم."],["دوباره","adverb","again","لطفاً دوباره بگویید."]]],["review_a1","A1 review",[["امروز","adverb","today","امروز وقت دارم."],["فردا","adverb","tomorrow","فردا می‌آیم."],["وقت","noun","time","وقت ندارم."],["دوست","noun","friend","او دوست من است."]]]]]
